from collections import Counter

def check_inclusion(s1: str, s2: str) -> bool:
    k = len(s1)
    if k > len(s2):
        return False
    need = Counter(s1)
    window = Counter(s2[:k])
    if window == need:
        return True
    for right in range(k, len(s2)):
        window[s2[right]] += 1
        leaving = s2[right - k]
        window[leaving] -= 1
        if window[leaving] == 0:
            del window[leaving]          # keeps the window small; since 3.10 == also ignores zero counts
        if window == need:
            return True
    return False

